SELECT name, location FROM bridge
UNION
SELECT name, location FROM mill;

SELECT name, location, length_meters, length_feet
FROM bridge
WHERE location LIKE '%Utah%' OR location LIKE '%Chad%' OR location LIKE '%Zion National Park%' OR location LIKE '%Glen Canyon National Recreation Area%' OR location LIKE '%Escalante Canyon%' OR location LIKE '%Natural Bridges National Monument%' OR location LIKE '%Dinosaur National Monument%' OR location LIKE '%Sanostee%';

SELECT name 
FROM architect 
WHERE nationality2 = "";
